func testUnidademedidasToManyAddOpUndManifestoEletronicos(t *testing.T) {
	var err error

	ctx := context.Background()
	tx := MustTx(boil.BeginTx(ctx, nil))
	defer func() { _ = tx.Rollback() }()

	var a Unidademedidas
	var b, c, d, e ManifestoEletronico

	seed := randomize.NewSeed()
	if err = randomize.Struct(seed, &a, unidademedidasDBTypes, false, strmangle.SetComplement(unidademedidasPrimaryKeyColumns, unidademedidasColumnsWithoutDefault)...); err != nil {
		t.Fatal(err)
	}
	foreigners := []*ManifestoEletronico{&b, &c, &d, &e}
	for _, x := range foreigners {
		if err = randomize.Struct(seed, x, manifestoEletronicoDBTypes, false, strmangle.SetComplement(manifestoEletronicoPrimaryKeyColumns, manifestoEletronicoColumnsWithoutDefault)...); err != nil {
			t.Fatal(err)
		}
	}

	if err := a.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}
	if err = b.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}
	if err = c.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}

	foreignersSplitByInsertion := [][]*ManifestoEletronico{
		{&b, &c},
		{&d, &e},
	}

	for i, x := range foreignersSplitByInsertion {
		err = a.AddUndManifestoEletronicos(ctx, tx, i != 0, x...)
		if err != nil {
			t.Fatal(err)
		}

		first := x[0]
		second := x[1]

		if a.UndID != first.UndID {
			t.Error("foreign key was wrong value", a.UndID, first.UndID)
		}
		if a.UndID != second.UndID {
			t.Error("foreign key was wrong value", a.UndID, second.UndID)
		}

		if first.R.Und != &a {
			t.Error("relationship was not added properly to the foreign slice")
		}
		if second.R.Und != &a {
			t.Error("relationship was not added properly to the foreign slice")
		}

		if a.R.UndManifestoEletronicos[i*2] != first {
			t.Error("relationship struct slice not set to correct value")
		}
		if a.R.UndManifestoEletronicos[i*2+1] != second {
			t.Error("relationship struct slice not set to correct value")
		}

		count, err := a.UndManifestoEletronicos().Count(ctx, tx)
		if err != nil {
			t.Fatal(err)
		}
		if want := int64((i + 1) * 2); count != want {
			t.Error("want", want, "got", count)
		}
	}
}
